"use client";

import { useEffect, useId, useRef, useState, type ComponentProps } from "react";

import { IconAlertCircle, IconInfo, IconPlus, IconTrash } from "@rhs-ui/icons";
import { CellInput } from "@rhs-ui/application/tiered-rates-editor/cell-input";
import {
  DEFAULT_LABELS,
  describeTiers,
  endOf,
  fill,
  formatNumber,
  refusalFor,
  tidyTiers,
  unitFor,
  widestRefusal,
  withAdded,
  withFrom,
  withRate,
  withoutTier,
  type Tier,
  type TierUnit,
  type TieredRatesEditorLabels,
} from "@rhs-ui/application/tiered-rates-editor/tiers";
import { Button } from "@rhs-ui/primitives/button";
import { CurrencyInput } from "@rhs-ui/primitives/currency-input";
import { Table, TableBody, TableCaption, TableCell, TableHead, TableHeader, TableRow } from "@rhs-ui/primitives/table";
import { cn } from "@/lib/utils";

export type { Tier, TierUnit, TieredRatesEditorLabels } from "@rhs-ui/application/tiered-rates-editor/tiers";

export interface TieredRatesEditorProps extends Omit<ComponentProps<"div">, "defaultValue" | "onChange" | "children"> {
  /** The tiers, first to last, when you control the editor: `{ from, rate }` each. A tier ends one below where the next begins. */
  value?: readonly Tier[];
  /** The tiers to begin with, when the editor keeps them itself. */
  defaultValue?: readonly Tier[];
  /** Called with all the tiers whenever one changes, a tier is added or one is removed. */
  onValueChange?: (value: Tier[]) => void;
  /** What the ranges count: "kg", "orders", or a pair for the plural, `{ one: "order", other: "orders" }`. Default "units". */
  unit?: TierUnit;
  /** The heading of the rate column, and the start of the note: "Price per unit", "Commission". Default "Rate". */
  rateLabel?: string;
  /** An ISO currency code. With it the rate is money: edited as an amount and stored in minor units (cents). Without it the rate is a plain number. */
  currency?: string;
  /** A mark after a plain rate: "%" for a commission. Not used with a currency. */
  rateSuffix?: string;
  /** The fewest tiers: removing stops there. Default 1. */
  minRows?: number;
  /** The most tiers: adding stops there. Default 10. */
  maxRows?: number;
  /** The language of the numbers and of the note. Default "en-US". */
  locale?: string;
  /** Turn the whole editor off. */
  disabled?: boolean;
  /** The words the editor says, for translation. */
  labels?: TieredRatesEditorLabels;
}

/**
 * An editable table of tiers for volume prices, weight-based shipping and
 * tiered commissions. Each row has a From, an automatic To (always one below
 * the next row's From; the last row says "and up") and a rate, so editing a
 * From moves the To above it and a gap or an overlap cannot be entered. A tier
 * that would end before it starts is refused, with the reason in words, once
 * typing pauses or the cell is left (so "7" on its way to "75" is never
 * refused), at once only when no further digit could help; the reason takes
 * the place of the note, so nothing moves. Add puts a tier after the last
 * one, removing a tier hands its range to the one before it, and a note under
 * the table says the resulting ranges in words. The fields are named by row
 * ("Tier 2, from"), numbers sit in tabular figures, and on a phone the table
 * fits without scrolling (below 20rem of width the Tier column is left out, the
 * fields keep their names), or else scrolls inside its own frame.
 */
export function TieredRatesEditor({
  value,
  defaultValue,
  onValueChange,
  unit = "units",
  rateLabel = "Rate",
  currency,
  rateSuffix,
  minRows = 1,
  maxRows = 10,
  locale = "en-US",
  disabled = false,
  labels,
  className,
  ...props
}: TieredRatesEditorProps) {
  const words = { ...DEFAULT_LABELS, ...labels };
  const base = useId();
  const [own, setOwn] = useState<readonly Tier[]>(defaultValue ?? []);
  // Why the last start was refused. It stays until something is changed, so it can still be read after the cell has put the old number back.
  const [refusal, setRefusal] = useState<string | null>(null);
  const [said, setSaid] = useState("");
  const focusAfter = useRef<string | null>(null);
  const tiers = tidyTiers(value ?? own);
  const count = (n: number) => formatNumber(n, 0, locale);
  const money = currency ? new Intl.NumberFormat(locale, { style: "currency", currency }) : null;
  const plain = new Intl.NumberFormat(locale, { maximumFractionDigits: 2 });
  const rateText = (rate: number) => (money ? money.format(rate / 100) : `${plain.format(rate)}${rateSuffix ?? ""}`);
  const note = describeTiers(tiers, { rateLabel, unit, locale, words, rate: rateText });
  const noteId = `${base}-note`;
  // Only an editor with a start to type into can refuse one.
  const reasonSample = tiers.length > 1 && !disabled ? widestRefusal(words, count) : null;

  // After an add or a remove the focus goes to a field that is still there, so the keyboard carries on where it was.
  useEffect(() => {
    if (focusAfter.current) {
      document.getElementById(focusAfter.current)?.focus();
      focusAfter.current = null;
    }
  });

  function commit(next: Tier[]) {
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  }

  function add() {
    const next = withAdded(tiers);
    const added = next[next.length - 1];
    setRefusal(null);
    commit(next);
    focusAfter.current = `${base}-rate-${next.length - 1}`;
    if (added) setSaid(fill(words.added, { tier: next.length, from: count(added.from) }));
  }

  function remove(index: number) {
    const next = withoutTier(tiers, index);
    setRefusal(null);
    commit(next);
    focusAfter.current = `${base}-rate-${Math.min(index, next.length - 1)}`;
    setSaid(index === 0 ? fill(words.removedFirst, { from: count(next[0]?.from ?? 1) }) : fill(words.removed, { tier: index + 1, into: index }));
  }

  return (
    <div data-slot="tiered-rates-editor" className={cn("@container overflow-hidden rounded-xl border border-border bg-card text-card-foreground shadow-xs", disabled && "opacity-60", className)} {...props}>
      <Table aria-describedby={noteId} className="min-w-0 @xs:min-w-[19.5rem] @xl:min-w-[36rem]">
        <TableCaption className="sr-only">{words.caption}</TableCaption>
        <TableHeader>
          <TableRow className="bg-muted/40 hover:bg-muted/40">
            <TableHead scope="col" className="hidden w-9 pr-0 pl-3 text-xs @xs:table-cell @xl:w-20 @xl:pr-3 @xl:pl-4">
              <span className="@xl:sr-only">{words.tierColumn}</span>
            </TableHead>
            <TableHead scope="col" className="w-[4.5rem] pr-2 pl-1.5 text-right text-xs @xs:w-[5.25rem] @xs:pr-4 @xl:w-36 @xl:pr-6 @xl:pl-3">
              {words.from} <span className="block font-normal @xl:inline">({unitFor(unit, 2, locale)})</span>
            </TableHead>
            <TableHead scope="col" className="w-12 pr-1 pl-1.5 text-right text-xs @xs:w-14 @xl:w-28 @xl:pr-6 @xl:pl-3" title={words.autoHint}>
              {words.to} <span className="block font-normal @xl:inline">({unitFor(unit, 2, locale)})</span>
              <span className="sr-only">, {words.autoHint}</span>
            </TableHead>
            <TableHead scope="col" className="pr-2 pl-1 text-left text-xs @xs:pr-3 @xs:pl-4 @xl:pr-6 @xl:pl-3 @xl:text-right">
              {rateLabel}
            </TableHead>
            <TableHead scope="col" className="w-9 pr-1 pl-0 @xl:w-14 @xl:pr-3">
              <span className="sr-only">{words.actionsColumn}</span>
            </TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {tiers.map((tier, index) => {
            const to = endOf(tiers, index);
            const number = index + 1;
            return (
              <TableRow key={index} className="hover:bg-transparent">
                <TableHead scope="row" className="hidden pr-0 pl-3 text-sm font-medium text-muted-foreground tabular-nums @xs:table-cell @xl:pr-3 @xl:pl-4 @xl:text-foreground">
                  <span aria-hidden="true" className="@xl:hidden">
                    {number}
                  </span>
                  <span className="sr-only @xl:not-sr-only">{fill(words.tier, { tier: number })}</span>
                </TableHead>
                <TableCell className="px-1 py-2 @xl:px-3">
                  {index === 0 ? (
                    <span className="ml-auto flex h-9 w-16 items-center justify-end rounded-md border border-dashed border-input bg-muted/40 px-3 text-sm tabular-nums @xs:w-[4.5rem] @xl:w-32">{count(tier.from)}</span>
                  ) : (
                    <CellInput
                      value={tier.from}
                      locale={locale}
                      disabled={disabled}
                      aria-label={fill(words.fromField, { tier: number })}
                      refuse={(next, settled) => refusalFor(tiers, index, next, words, count, settled)}
                      onRefuse={setRefusal}
                      onValueChange={(from) => {
                        if (from !== null) commit(withFrom(tiers, index, from));
                      }}
                      className="ml-auto w-16 @xs:w-[4.5rem] @xl:w-32"
                    />
                  )}
                </TableCell>
                <TableCell className="px-1 py-2 text-right text-sm text-muted-foreground tabular-nums @xl:px-3">
                  <span className="block px-0 whitespace-nowrap @xl:px-3">{to === null ? words.andUp : count(to)}</span>
                </TableCell>
                <TableCell className="px-1 py-2 @xl:px-3">
                  {currency ? (
                    <CurrencyInput
                      id={`${base}-rate-${index}`}
                      value={tier.rate}
                      currency={currency}
                      locale={locale}
                      disabled={disabled}
                      aria-label={fill(words.rateField, { tier: number, rate: rateLabel })}
                      onValueChange={(rate) => {
                        setRefusal(null);
                        commit(withRate(tiers, index, rate));
                      }}
                      className="mr-auto w-[5.25rem] @xs:w-[6.5rem] @xl:mr-0 @xl:ml-auto @xl:w-40"
                    />
                  ) : (
                    <CellInput
                      id={`${base}-rate-${index}`}
                      value={tier.rate}
                      decimals={2}
                      suffix={rateSuffix}
                      locale={locale}
                      disabled={disabled}
                      aria-label={fill(words.rateField, { tier: number, rate: rateLabel })}
                      onValueChange={(rate) => {
                        setRefusal(null);
                        commit(withRate(tiers, index, rate));
                      }}
                      className="mr-auto w-[5.25rem] @xs:w-[6.5rem] @xl:mr-0 @xl:ml-auto @xl:w-40"
                    />
                  )}
                </TableCell>
                <TableCell className="py-2 pr-1 pl-0 text-right @xl:pr-3">
                  <Button type="button" variant="ghost" size="icon-sm" disabled={disabled || tiers.length <= minRows} aria-label={fill(words.remove, { tier: number })} onClick={() => remove(index)} className="text-muted-foreground hover:text-foreground">
                    <IconTrash aria-hidden="true" />
                  </Button>
                </TableCell>
              </TableRow>
            );
          })}
        </TableBody>
      </Table>

      <div className="flex items-center justify-between gap-3 border-t border-border px-4 py-3">
        <Button type="button" variant="outline" size="sm" disabled={disabled || tiers.length >= maxRows} onClick={add}>
          <IconPlus aria-hidden="true" />
          {words.add}
        </Button>
      </div>

      {/* The note under the table is also where the reason a start was refused is shown, on top of it. The band is as tall as the longer of the two (the reason is measured from an unseen sample), so a reason covers the note exactly and nothing moves when it comes or goes. */}
      <div className="relative grid">
        <p id={noteId} className="col-start-1 row-start-1 flex border-t border-border bg-muted/30 px-4 py-3 text-xs leading-5 text-muted-foreground">
          <span className="my-auto flex items-start gap-2.5">
            <IconInfo aria-hidden="true" className="mt-0.5 size-4 shrink-0" />
            <span>{note}</span>
          </span>
        </p>

        {reasonSample ? (
          <p aria-hidden="true" className="invisible col-start-1 row-start-1 flex gap-2.5 border-t border-transparent px-4 py-3 text-xs leading-5 font-medium select-none">
            <span className="size-4 shrink-0" />
            <span>{reasonSample}</span>
          </p>
        ) : null}

        {/* Kept in the page when empty, with no size of its own: a live region that appears together with its message is often never read. */}
        <div role="status" aria-live="polite" className="absolute inset-x-0 bottom-0 flex flex-col not-empty:min-h-full">
          {refusal ? (
            <p data-slot="tiered-rates-editor-refusal" className="flex grow border-t border-destructive/30 bg-card px-4 py-3 text-xs leading-5 font-medium text-destructive">
              <span className="my-auto flex items-start gap-2.5">
                <IconAlertCircle aria-hidden="true" className="mt-0.5 size-4 shrink-0" />
                <span>{refusal}</span>
              </span>
            </p>
          ) : null}
        </div>
      </div>

      <p role="status" aria-live="polite" className="sr-only">
        {said}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState, type ComponentProps } from "react";

import { cleanTyping, formatNumber, parseNumber } from "@rhs-ui/application/tiered-rates-editor/tiers";
import { fieldSurface } from "@rhs-ui/primitives/input";
import { cn } from "@/lib/utils";

/** How long typing must pause before the number is passed on, in ms. */
const SETTLE = 300;
/** How long it must pause before a number that is not allowed yet is called refused, in ms: a slow typist may be on the way to one that is. */
const PATIENCE = 800;

export interface CellInputProps extends Omit<ComponentProps<"input">, "value" | "defaultValue" | "onChange" | "type" | "prefix"> {
  /** The number, or `null` while the cell is empty. */
  value: number | null;
  /** Called with a number that is accepted once typing pauses, and when the cell is left or Enter is pressed, so what depends on it follows. */
  onValueChange: (value: number | null) => void;
  /**
   * The reason a number is refused, or `null` when it is fine. A refused number is never passed on. `settled` is
   * false while the person is still typing, when only a number that more digits cannot repair should be refused.
   */
  refuse?: (value: number | null, settled: boolean) => string | null;
  /** Told the reason when a number is refused, and `null` when typing is fine again. */
  onRefuse?: (reason: string | null) => void;
  /** Digits after the decimal mark. 0, the default, is whole numbers. */
  decimals?: number;
  locale: string;
  /** A mark after the number: "%". */
  suffix?: string;
}

/**
 * A number in a table cell: quiet text on the field surface, right-aligned in
 * tabular figures. The number is passed on when typing pauses (and when the
 * cell is left or Enter is pressed), so "60" is never passed on as "6" on its
 * way. What was typed is judged by `refuse` only when typing settles, because
 * "7" may be on its way to "75": until then only a number that more digits
 * cannot repair is marked invalid at once, and nothing refused is passed on.
 * Leaving a refused cell shows the last number that was passed on again.
 */
export function CellInput({ value, onValueChange, refuse, onRefuse, decimals = 0, locale, suffix, className, onFocus, onBlur, onKeyDown, ...props }: CellInputProps) {
  const [draft, setDraft] = useState<string | null>(null);
  const [refused, setRefused] = useState(false);
  const pending = useRef<number | undefined>(undefined);
  // The latest callbacks, so a number that waits for typing to pause is judged and passed on by what the editor is now, not by what it was.
  const latest = useRef({ onValueChange, refuse, onRefuse });

  useEffect(() => {
    latest.current = { onValueChange, refuse, onRefuse };
  });
  useEffect(() => () => window.clearTimeout(pending.current), []);

  /** Shows the reason a number is refused, or withdraws it. */
  function say(reason: string | null) {
    setRefused(reason !== null);
    latest.current.onRefuse?.(reason);
  }

  /** Judges a number for good: it is refused with its reason, or passed on. */
  function settle(number: number | null) {
    const reason = latest.current.refuse ? latest.current.refuse(number, true) : null;
    if (reason !== null) {
      say(reason);
    } else {
      say(null);
      latest.current.onValueChange(number);
    }
  }

  function typed(text: string) {
    const clean = cleanTyping(text, decimals);
    const number = parseNumber(clean, decimals);
    const judge = latest.current.refuse;
    setDraft(clean);
    window.clearTimeout(pending.current);
    // Only a number that more digits cannot repair is refused while typing. Anything else is judged when typing pauses, so a valid number never flashes red on its first digits.
    const early = judge ? judge(number, false) : null;
    say(early);
    if (early !== null) return;
    // An emptied cell is judged when it is left: it is most likely about to be typed into.
    if (judge && number === null) return;
    pending.current = window.setTimeout(() => settle(number), judge && judge(number, true) !== null ? PATIENCE : SETTLE);
  }

  return (
    <div
      data-slot="cell-input"
      className={cn(
        fieldSurface,
        "flex h-9 min-w-0 items-center px-3 focus-within:border-ring focus-within:ring-[3px] focus-within:ring-ring/40 has-[input[aria-invalid=true]]:border-destructive has-[input:disabled]:opacity-50",
        className,
      )}
    >
      <input
        type="text"
        inputMode={decimals > 0 ? "decimal" : "numeric"}
        autoComplete="off"
        value={draft ?? (value === null ? "" : formatNumber(value, decimals, locale))}
        aria-invalid={refused || undefined}
        onFocus={(event) => {
          const field = event.currentTarget;
          setDraft(value === null ? "" : String(value));
          // After the plain number has replaced the grouped one, so the whole of it is what gets selected.
          requestAnimationFrame(() => field.select());
          onFocus?.(event);
        }}
        onChange={(event) => typed(event.target.value)}
        onKeyDown={(event) => {
          onKeyDown?.(event);
          if (event.defaultPrevented || event.key !== "Enter" || draft === null) return;
          const number = parseNumber(draft, decimals);
          // Nothing is waiting, so a form around the table may take the Enter. Otherwise Enter settles what was typed, now, and the form does not submit half-way.
          if (number === value && !refused) return;
          event.preventDefault();
          window.clearTimeout(pending.current);
          settle(number);
        }}
        onBlur={(event) => {
          // Leaving the cell judges what was typed if it has not been yet. A refused number is not kept: the cell shows the last good one again, and the reason stays readable.
          window.clearTimeout(pending.current);
          if (draft !== null) {
            const number = parseNumber(draft, decimals);
            if (number !== value) settle(number);
          }
          setDraft(null);
          setRefused(false);
          onBlur?.(event);
        }}
        className="min-w-0 flex-1 bg-transparent text-right tabular-nums outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed"
        {...props}
      />
      {suffix ? (
        <span aria-hidden="true" className="ml-1 text-muted-foreground">
          {suffix}
        </span>
      ) : null}
    </div>
  );
}

/** One tier of a rate table: the first amount it covers, and what that amount costs. A tier ends where the next one begins. */
export interface Tier {
  /** The first amount the tier covers, a whole number. The first tier starts where you start it and cannot be moved. */
  from: number;
  /** The rate of the tier, or `null` while it has none. In minor units (cents) when the editor has a `currency`, otherwise the plain number. */
  rate: number | null;
}

/** What the ranges count: one word, or the word in its singular and plural ("order", "orders"). */
export type TierUnit = string | { one: string; other: string };

/** The words the editor says, for translation. A `{name}` mark in a sentence is filled in. */
export interface TieredRatesEditorLabels {
  /** Names the table for a screen reader. Default "Rate tiers". */
  caption?: string;
  /** The row header; `{tier}` is its number. Default "Tier {tier}". */
  tier?: string;
  /** The heading of the column of row headers, which only a screen reader hears. Default "Tier". */
  tierColumn?: string;
  /** The heading of the first column of numbers. Default "From". */
  from?: string;
  /** The heading of the second. Default "To". */
  to?: string;
  /** What a screen reader and a tooltip say about the To column: it is worked out, not typed. Default "set by the next tier". */
  autoHint?: string;
  /** The heading of the column of remove buttons, which only a screen reader hears. Default "Actions". */
  actionsColumn?: string;
  /** What the last tier says in the To column. Default "and up". */
  andUp?: string;
  /** Names a From field; `{tier}`. Default "Tier {tier}, from". */
  fromField?: string;
  /** Names a rate field; `{tier}` and `{rate}`, the rate heading. Default "Tier {tier}, {rate}". */
  rateField?: string;
  /** Names the button that removes a tier; `{tier}`. Default "Remove tier {tier}". */
  remove?: string;
  /** The button that adds a tier. Default "Add tier". */
  add?: string;
  /** The note under the table; `{rate}` is the rate heading and `{ranges}` the list of ranges. Default "{rate} is {ranges}." */
  note?: string;
  /** One range with its rate, in the note; `{rate}` and `{range}`. Default "{rate} for {range}". */
  rangeRate?: string;
  /** A range in words; `{from}`, `{to}` and `{unit}`. Default "{from} to {to} {unit}". */
  range?: string;
  /** A range of one amount; `{from}` and `{unit}`. Default "{from} {unit}". */
  rangeOne?: string;
  /** The last range; `{from}` and `{unit}`. Default "{from} {unit} and up". */
  rangeOpen?: string;
  /** What the note says for a tier that has no rate. Default "no rate yet". */
  noRate?: string;
  /** Why a start is refused when it is too low; `{tier}`, `{previous}`, `{value}` and `{min}`. Default "Tier {tier} cannot start at {value}: tier {previous} would end before it starts. Use {min} or more." */
  refuseLow?: string;
  /** Why a start is refused when it is too high; `{tier}`, `{next}`, `{nextFrom}`, `{value}` and `{max}`. Default "Tier {tier} cannot start at {value}: it would end before it starts, because tier {next} begins at {nextFrom}. Use {max} or less." */
  refuseHigh?: string;
  /** Why an empty start is refused; `{tier}`. Default "Tier {tier} needs a number to start at." */
  refuseEmpty?: string;
  /** Said after a tier is added; `{tier}` and `{from}`. Default "Tier {tier} added, starting at {from}." */
  added?: string;
  /** Said after a tier is removed; `{tier}` and `{into}`, the tier that took over its range. Default "Tier {tier} removed. Its range now belongs to tier {into}." */
  removed?: string;
  /** Said after the first tier is removed, because no tier is before it; `{from}` is where the new first tier starts. Default "First tier removed. The next one now starts at {from} and is tier 1." */
  removedFirst?: string;
}

export const DEFAULT_LABELS = {
  caption: "Rate tiers",
  tier: "Tier {tier}",
  tierColumn: "Tier",
  from: "From",
  to: "To",
  autoHint: "set by the next tier",
  actionsColumn: "Actions",
  andUp: "and up",
  fromField: "Tier {tier}, from",
  rateField: "Tier {tier}, {rate}",
  remove: "Remove tier {tier}",
  add: "Add tier",
  note: "{rate} is {ranges}.",
  rangeRate: "{rate} for {range}",
  range: "{from} to {to} {unit}",
  rangeOne: "{from} {unit}",
  rangeOpen: "{from} {unit} and up",
  noRate: "no rate yet",
  refuseLow: "Tier {tier} cannot start at {value}: tier {previous} would end before it starts. Use {min} or more.",
  refuseHigh: "Tier {tier} cannot start at {value}: it would end before it starts, because tier {next} begins at {nextFrom}. Use {max} or less.",
  refuseEmpty: "Tier {tier} needs a number to start at.",
  added: "Tier {tier} added, starting at {from}.",
  removed: "Tier {tier} removed. Its range now belongs to tier {into}.",
  removedFirst: "First tier removed. The next one now starts at {from} and is tier 1.",
} satisfies Required<TieredRatesEditorLabels>;

export type Words = Required<TieredRatesEditorLabels>;

/** Fills `{name}` marks in a sentence. A mark with no value stays as it is. */
export function fill(template: string, values: Record<string, string | number>): string {
  return template.replace(/\{(\w+)\}/g, (mark, key: string) => (key in values ? String(values[key]) : mark));
}

/** The unit as a word for a number: a plain unit is used as it is, a pair is chosen by the plural rules of the language. */
export function unitFor(unit: TierUnit, count: number, locale: string): string {
  if (typeof unit === "string") return unit;
  return new Intl.PluralRules(locale).select(count) === "one" ? unit.one : unit.other;
}

/**
 * The tiers as the editor can work with them: in order, each start a whole
 * number above the one before it. A value that arrives out of order or with
 * two tiers starting at the same place is repaired, not trusted, because the
 * To column would otherwise show a range that ends before it starts. An empty
 * value is one tier from 1.
 */
export function tidyTiers(tiers: readonly Tier[]): Tier[] {
  const sorted = [...tiers].map((tier) => ({ from: Math.max(0, Math.round(tier.from)), rate: tier.rate })).sort((a, b) => a.from - b.from);
  if (sorted.length === 0) return [{ from: 1, rate: null }];
  const out: Tier[] = [];
  for (const tier of sorted) {
    const before = out[out.length - 1];
    out.push(before && tier.from <= before.from ? { ...tier, from: before.from + 1 } : tier);
  }
  return out;
}

/** Where tier `index` (from the second on) may start: after the tier before begins, and before the tier after begins. */
export function allowedFrom(tiers: readonly Tier[], index: number): { min: number; max: number } {
  const before = tiers[index - 1];
  const after = tiers[index + 1];
  return { min: before ? before.from + 1 : 0, max: after ? after.from - 1 : Number.POSITIVE_INFINITY };
}

/**
 * Why a start is refused, in words, or `null` when it is fine. `number` writes a
 * number the way the person reads it. While the person is still typing
 * (`settled` false) only a start that no further digit can repair is refused:
 * digits only make a number larger, so one above the top of its range is lost
 * for good, while one below the bottom ("7" on its way to "75") or an empty
 * cell may still become fine.
 */
export function refusalFor(tiers: readonly Tier[], index: number, value: number | null, words: Words, number: (n: number) => string, settled = true): string | null {
  const { min, max } = allowedFrom(tiers, index);
  if (!settled && (value === null || value <= max)) return null;
  if (value === null) return fill(words.refuseEmpty, { tier: index + 1 });
  if (value < min) return fill(words.refuseLow, { tier: index + 1, previous: index, value: number(value), min: number(min) });
  const after = tiers[index + 1];
  if (value > max && after) return fill(words.refuseHigh, { tier: index + 1, next: index + 2, nextFrom: number(after.from), value: number(value), max: number(max) });
  return null;
}

/** The longest reason a start can be refused with, written with long numbers. It is never shown: it measures how much room a reason can need, so the room can be kept free. */
export function widestRefusal(words: Words, number: (n: number) => string): string {
  const big = number(99999999);
  const values = { tier: 10, previous: 9, next: 11, nextFrom: big, value: big, min: big, max: big };
  return [words.refuseLow, words.refuseHigh, words.refuseEmpty].map((text) => fill(text, values)).reduce((longest, text) => (text.length > longest.length ? text : longest));
}

/** The tiers with the start of one of them moved. */
export function withFrom(tiers: readonly Tier[], index: number, from: number): Tier[] {
  return tiers.map((tier, at) => (at === index ? { ...tier, from } : tier));
}

/** The tiers with the rate of one of them changed. */
export function withRate(tiers: readonly Tier[], index: number, rate: number | null): Tier[] {
  return tiers.map((tier, at) => (at === index ? { ...tier, rate } : tier));
}

/** The next round number at or above `target`: 1, 2, 5, 10, 20, 50, 100 and so on. */
function roundUp(target: number): number {
  const power = 10 ** Math.floor(Math.log10(Math.max(1, target)));
  for (const step of [1, 2, 5, 10]) if (step * power >= target) return step * power;
  return 10 * power;
}

/** A tier after the last one. It starts at a round number about twice as far on, and has no rate yet. */
export function withAdded(tiers: readonly Tier[]): Tier[] {
  const last = tiers[tiers.length - 1];
  const from = last ? roundUp(Math.max(last.from + 1, last.from * 2)) : 1;
  return [...tiers, { from, rate: null }];
}

/**
 * The tiers without one of them. Its range goes to the tier before it, which
 * simply runs on to the next start. The first tier has none before it, so the
 * tier after it starts where it did.
 */
export function withoutTier(tiers: readonly Tier[], index: number): Tier[] {
  if (index === 0 && tiers.length > 1) {
    const [first, second, ...rest] = tiers;
    return first && second ? [{ ...second, from: first.from }, ...rest] : [...tiers];
  }
  return tiers.filter((_, at) => at !== index);
}

/** The last amount of tier `index`: one below the start of the next tier, or `null` for the last tier. */
export function endOf(tiers: readonly Tier[], index: number): number | null {
  const after = tiers[index + 1];
  return after ? after.from - 1 : null;
}

/** A number as people read it: grouped for the language, with at most `decimals` digits after the point. */
export function formatNumber(value: number, decimals: number, locale: string): string {
  return new Intl.NumberFormat(locale, { minimumFractionDigits: decimals, maximumFractionDigits: decimals }).format(value);
}

/** The text a person has typed as a number: both the point and the comma count as the decimal mark. Empty or unreadable is `null`. */
export function parseNumber(text: string, decimals: number): number | null {
  const cleaned = text.replace(",", ".").replace(decimals > 0 ? /[^\d.]/g : /[^\d]/g, "");
  if (cleaned === "" || cleaned === ".") return null;
  const value = Number(cleaned);
  return Number.isFinite(value) ? value : null;
}

/** What may be typed: digits, and with decimals one decimal mark and no more digits after it than are kept. */
export function cleanTyping(text: string, decimals: number): string {
  if (decimals === 0) return text.replace(/\D/g, "");
  const swapped = text.replace(",", ".").replace(/[^\d.]/g, "");
  const [whole = "", ...rest] = swapped.split(".");
  return rest.length ? `${whole}.${rest.join("").slice(0, decimals)}` : whole;
}

/** The whole table in words, for the note under it: "Price per unit is €12.00 for 1 to 9 units, €10.50 for 10 to 49 units and €9.00 for 50 units and up." */
export function describeTiers(tiers: readonly Tier[], context: { rateLabel: string; unit: TierUnit; locale: string; words: Words; rate: (rate: number) => string }): string {
  const { rateLabel, unit, locale, words, rate } = context;
  const count = (n: number) => formatNumber(n, 0, locale);
  const parts = tiers.map((tier, index) => {
    const to = endOf(tiers, index);
    const from = count(tier.from);
    const range =
      to === null
        ? fill(words.rangeOpen, { from, unit: unitFor(unit, tier.from, locale) })
        : to === tier.from
          ? fill(words.rangeOne, { from, unit: unitFor(unit, tier.from, locale) })
          : fill(words.range, { from, to: count(to), unit: unitFor(unit, to, locale) });
    return fill(words.rangeRate, { rate: tier.rate === null ? words.noRate : rate(tier.rate), range });
  });
  return fill(words.note, { rate: rateLabel, ranges: new Intl.ListFormat(locale, { style: "long", type: "conjunction" }).format(parts) });
}
